import ast, csv, json
from pathlib import Path
base=json.loads(Path('memory/baseline_forecasts.json').read_text())
active={}
with open('market.csv', newline='') as f:
    for r in csv.DictReader(f):
        if r['is_resolved'].lower()=='false':
            active[r['qid']]=ast.literal_eval(r['my_prediction']) if r['my_prediction'] else None
expected={'591655','800177','669987','879060','89772','893744'}
diffs={q for q,p in active.items() if base.get(q)"'!=p}
invalid=[]
for q,p in base.items():
    if q in active:
        if not isinstance(p,dict) or len(p)>5 or sum(p.values())>1.000000001 or any(v<0 or v>1 for v in p.values()):
            invalid.append((q,p))
print('"'active_market',len(active))
print('baseline_active_covered',sum(q in base for q in active))
print('day_snapshot_diffs',sorted(diffs))
print('diffs_match_submissions',diffs==expected)
print('invalid_active_forecasts',invalid)
print('note_exists',Path('memory/2026-04-07.md').exists())
PY"

